test('TP032 Receive resumes only the captured wallet after phrase confirmation and cancellation, incomplete confirmation, lock or navigation never opens QR',async t=>{
 const accounts=[{id:'a',network:'testnet',index:0,address:'PUBLIC-A'},{id:'b',network:'testnet',index:0,address:'PUBLIC-B'}];
 for(const outcome of ['verified','cancel','unverified','lock','navigate','close','refresh-navigation']){
  const h=await rendererHarness({state:{accounts,environment:'mainnet',recoveryConfirmed:false}});t.after(h.close);await h.$('accountgroups').querySelector('.openwallet').onclick();await h.invoke('receive');const gate=deferred();h.handlers.confirmRecovery=()=>gate.promise;
  const work=h.invoke('receiverecovery');await tick();await h.invoke('receiverecovery');assert.equal(h.calls.filter(c=>c.method==='confirmRecovery').length,1);
  if(outcome==='lock')h.notifyLock();if(outcome==='navigate')await h.$('accountgroups').querySelector('[data-account-id="b"] .openwallet').onclick();if(outcome==='close')middle(h,h.$('viewtabs').querySelector('[data-wallet-id="a"]'));
  if(outcome==='cancel')gate.reject(Error('REQUEST_CANCELLED'));
  else {h.setState({accounts,environment:'mainnet',recoveryConfirmed:outcome!=='unverified'});if(outcome==='refresh-navigation'){const state=deferred();h.handlers.accounts=()=>state.promise;gate.resolve({});await tick();middle(h,h.$('viewtabs').querySelector('[data-wallet-id="a"]'));state.resolve({locked:false,walletExists:true,vaultState:'present',accounts,environment:'mainnet',recoveryConfirmed:true})}else gate.resolve({})}
  await work;const receives=h.calls.filter(c=>c.method==='receive');assert.equal(receives.length,outcome==='verified'?1:0,outcome);if(receives.length)assert.deepEqual(receives[0].body,{accountId:'a'});assert.equal(h.$('receiverecoverydialog').hidden,true);assert.ok(!h.calls.some(c=>c.method==='send'));
  if(outcome==='cancel'){assert.equal(h.$('operationerror').hidden,false);assert.match(h.$('operationerror').textContent,/cancelled/)}
 }
 const locked=await rendererHarness({state:{locked:true,walletExists:true,vaultState:'present'}});t.after(locked.close);await locked.invoke('sendrecovery');assert.ok(!locked.calls.some(c=>c.method==='confirmRecovery'));await locked.invoke('receiverecovery');assert.ok(!locked.calls.some(c=>c.method==='confirmRecovery'));
});

